-- User module (user.db)
-- Accounts, sign-in state and what each account may reach.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE "users" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            full_name TEXT NOT NULL,
            email TEXT NOT NULL UNIQUE,
            phone TEXT DEFAULT '',
            password_hash TEXT NOT NULL,
            role TEXT NOT NULL CHECK (role IN ('admin', 'hr', 'finance', 'budget', 'procurement', 'payroll', 'inventory', 'auditor', 'employee', 'member')),
            status TEXT NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Disabled')),
            last_login TEXT,
                username TEXT,
                employee_id INTEGER,
                must_change_password INTEGER NOT NULL DEFAULT 0,
                password_updated_at TEXT,
                department_id INTEGER,
                position_id INTEGER, ms_object_id TEXT, ms_tenant_id TEXT, ms_linked_at TEXT, failed_login_count INTEGER NOT NULL DEFAULT 0, lock_state TEXT NOT NULL DEFAULT 'unlocked', lock_until TEXT, locked_at TEXT, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT, directory_connection_id INTEGER, directory_object_id TEXT, directory_upn TEXT, directory_managed INTEGER NOT NULL DEFAULT 0, directory_departed INTEGER NOT NULL DEFAULT 0, directory_synced_at TEXT);

CREATE TABLE login_attempts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                identifier TEXT NOT NULL,
                ip TEXT NOT NULL DEFAULT '',
                attempted_at TEXT NOT NULL
            );

CREATE TABLE password_reset_requests (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                identifier TEXT NOT NULL,
                user_id INTEGER,
                ip TEXT NOT NULL DEFAULT '',
                requested_at TEXT NOT NULL
            );

CREATE TABLE password_reset_tokens (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                token_hash TEXT NOT NULL UNIQUE,
                requested_ip TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                used_at TEXT
            );

CREATE TABLE username_sequence (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            next_number INTEGER NOT NULL
        );

CREATE TABLE user_roles (
        user_id INTEGER NOT NULL,
        role_key TEXT NOT NULL,
        assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (user_id, role_key),
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);

CREATE TABLE "user_permissions" (
            user_id INTEGER NOT NULL,
            module TEXT NOT NULL CHECK (module IN ('hr', 'finance', 'budget', 'payroll', 'inventory', 'accounts', 'procurement', 'approvals', 'audit', 'letters', 'integrations')),
            allowed INTEGER NOT NULL CHECK (allowed IN (0, 1)),
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (user_id, module),
            FOREIGN KEY (user_id) REFERENCES users(id)
        );

CREATE TABLE user_permission_grants (
        user_id INTEGER NOT NULL,
        permission TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 1 CHECK (allowed IN (0, 1)),
        granted_by INTEGER,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (user_id, permission),
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
        FOREIGN KEY (granted_by) REFERENCES users(id) ON DELETE SET NULL
    );

CREATE INDEX idx_users_department
            ON users(department_id);
CREATE INDEX idx_users_directory_connection ON users(directory_connection_id);
CREATE UNIQUE INDEX idx_users_directory_object ON users(directory_connection_id, directory_object_id) WHERE directory_object_id IS NOT NULL AND directory_object_id <> '';
CREATE INDEX idx_users_employee ON users(employee_id);
CREATE UNIQUE INDEX idx_users_ms_object ON users(ms_object_id);
CREATE INDEX idx_users_position
            ON users(position_id);
CREATE INDEX idx_users_status
                ON users(status);
CREATE INDEX idx_users_username ON users(username);
CREATE INDEX idx_login_attempts_identifier ON login_attempts(identifier, attempted_at);
CREATE INDEX idx_login_attempts_ip ON login_attempts(ip, attempted_at);
CREATE INDEX idx_password_reset_identifier ON password_reset_requests(identifier, requested_at);
CREATE INDEX idx_password_reset_ip ON password_reset_requests(ip, requested_at);
CREATE INDEX idx_reset_tokens_user ON password_reset_tokens(user_id, created_at);
CREATE INDEX idx_user_roles_user ON user_roles(user_id);
CREATE INDEX idx_user_permission_grants_user ON user_permission_grants (user_id);
